    async Task LoadFile(IFileListEntry file)
    {
        string[] tokens = file.Name.Split(new char[] { '_', '.' }, StringSplitOptions.RemoveEmptyEntries);

        if(tokens[2] != "xlsx")
        {
            errorMsg = "Моля качете файл с разширение .xlsx";
        }
        // So the UI updates to show progress
        file.OnDataRead += (sender, eventArgs) => InvokeAsync(StateHasChanged);

        // Just load into .NET memory to show it can be done
        // Alternatively it could be saved to disk, or parsed in memory, or similar
        var ms = new System.IO.MemoryStream();
        await file.Data.CopyToAsync(ms);
        bool result = await service.UploadExamAsync(ms, tokens[0], int.Parse(tokens[1]));

        if (!result)
        {
            errorMsg = "Моля уверете се, че всичко е наред с файла, който качвате!";
        }
        else
        {
            successMsg = $"Успешно качихте матура {tokens[0]} - {tokens[1]}";
        }
    }

